<?php require_once 'config/helpers.php'; if(is_customer()) redirect('customer/dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$role=$_POST['role']??'customer';if($role==='admin'){$st=$pdo->prepare('SELECT * FROM admins WHERE email=?');$st->execute([$email]);$u=$st->fetch();if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$u['id'];$_SESSION['admin_name']=$u['name'];redirect('admin/dashboard.php');}}else{$st=$pdo->prepare('SELECT * FROM customers WHERE email=?');$st->execute([$email]);$u=$st->fetch();if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['customer_id']=$u['id'];$_SESSION['customer_name']=$u['full_name'];redirect('customer/dashboard.php');}}$error='Email or password is incorrect.';} $page_title='Login';include 'includes/header.php'; ?>
<div class="form-wrap panel"><h1 class="section-title">Welcome Back</h1><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div><label>Login as</label><select name="role"><option value="customer">Customer</option><option value="admin" <?= (($_GET['role']??'')==='admin'?'selected':'') ?>>Administrator</option></select></div><div><label>Email address</label><input type="email" name="email" required autocomplete="username"></div><div><label>Password</label><input type="password" name="password" required autocomplete="current-password"></div><button>Login Securely</button></form><p class="center">New customer? <a href="register.php">Create account</a></p><p class="center small"><a href="setup_admin.php">First-time admin setup</a> (remove this file after setup)</p></div><?php include 'includes/footer.php'; ?>
